    no_initial_focus = true,
})

-- BLUR & FULLSCREEN

hl.window_rule({
    name  = "noblur_208",
    match = {
        tag = "games*",
    },
    blur = false,
})

hl.window_rule({
    name  = "fullscreen_209",
    match = {
        tag = "games*",
    },
    fullscreen = true,
})

--This not gonna take the focus to the window that appears when hovering over some of the parts of the IntelliJ Products 

hl.window_rule({
    name  = "noinitialfocus_213",
    match = {
        class = "^(jetbrains-*)",
    },
    no_initial_focus = true,
})

hl.window_rule({
    name  = "noinitialfocus_214",
    match = {
        title = "^(wind.*)$",
    },
    no_initial_focus = true,
})

